<template>
  <div class="review-page">
    <PageHeader title="事件研判" />
    <section class="case-toolbar">
      <div><span class="eyebrow">当前事件</span><h2>{{ currentCase?.title || '选择事件' }}</h2><p>{{ currentCase ? `快照更新于 ${formatTime(currentCase.updated_at)}` : '按事件名称或复核条目搜索' }}</p></div>
      <a-space :size="8" wrap>
        <a-select v-model:value="selectedCaseId" show-search allow-clear :filter-option="false" :options="caseOptions" :loading="searching" class="case-select" placeholder="搜索事件" aria-label="选择事件" @search="handleCaseSearch" @change="handleCaseChange" />
        <a-button :loading="loading" @click="refreshCurrentCase">刷新</a-button>
        <a-button :disabled="!currentCase" :loading="studentRefreshing" @click="refreshStudent">重新研判</a-button>
        <a-button type="primary" :disabled="!currentCase" @click="openTeacherReview">启动智能审计</a-button>
      </a-space>
    </section>
    <RiskSectionTabs :event-id="riskScopeEventId" :case-id="riskScopeCaseId" />
    <a-spin :spinning="loading">
      <a-empty v-if="!currentCase" description="暂无可研判事件" />
      <template v-else>
        <section class="overview-strip" aria-label="研判概览">
          <div class="overview-main"><span class="eyebrow">当前快照的初步研判</span><strong :class="`is-${currentCase.preliminary_finding.conclusion}`">{{ conclusionLabel(currentCase.preliminary_finding.conclusion) }}</strong><p>{{ preliminaryNarrative }}</p></div>
          <div class="overview-stat"><span>材料充分度</span><strong>{{ sufficiencyLabel(currentCase.evidence_sufficiency) }}</strong></div>
          <div class="overview-stat"><span>处置紧迫度</span><strong>{{ urgencyLabel(currentCase.urgency) }}</strong></div>
          <div class="overview-stat"><span>当前建议</span><strong>{{ dispositionLabel(currentCase.disposition) }}</strong></div>
        </section>
        <section class="workbench-grid">
          <section class="analysis-column" aria-label="研判链">
            <header class="chain-heading"><h3>本案研判链</h3><span class="chain-snapshot">{{ studentAssessment?.snapshot_id ? '结果已绑定当前快照' : '正在读取当前快照结果' }}</span></header>
            <ol class="review-chain">
              <li class="review-step" :class="`state-${studentStateKey}`">
                <div class="step-rail"><span class="step-number">1</span></div>
                <details class="step-body">
                  <summary class="step-heading" aria-label="展开或收起内容风险研判"><div><span class="eyebrow">初步研判</span><h4>内容风险</h4></div><a-tag :color="studentStateColor">{{ studentStateLabel }}</a-tag></summary>
                  <div class="step-content">
                  <a-spin :spinning="studentLoading">
                    <div v-if="studentAssessment" class="axis-grid">
                      <article v-for="axis in studentAssessment.axes" :key="axis.task" class="axis-panel">
                        <div class="axis-heading"><span>{{ taskLabel(axis.task) }}</span><a-tag :color="axisStatusColor(axis.status)">{{ axisStatusLabel(axis.status) }}</a-tag></div>
                        <template v-if="axis.status === 'completed'"><strong :class="`is-${axis.conclusion}`">{{ conclusionLabel(axis.conclusion || 'insufficient_evidence') }}</strong><dl><div><dt>风险分</dt><dd>{{ percent(axis.risk_score) }}</dd></div><div><dt>阈值</dt><dd>{{ percent(axis.threshold) }}</dd></div></dl><p>{{ axis.rationale }}</p></template>
                        <p v-else class="muted">{{ axis.rationale || '当前快照尚未形成可用结果。' }}</p>
                      </article>
                    </div>
                    <a-alert v-else type="info" show-icon message="尚未读取初步研判结果" description="可重新研判当前快照，系统不会以规则或静态文本补造结论。" />
                  </a-spin>
                  </div>
                </details>
              </li>
              <li class="review-step" :class="`state-${auditStateKey}`">
                <div class="step-rail"><span class="step-number">2</span></div>
                <details class="step-body">
                  <summary class="step-heading" aria-label="展开或收起智能审计"><div><span class="eyebrow">人工触发</span><h4>智能审计</h4></div><a-tag :color="auditStateColor">{{ auditStateLabel }}</a-tag></summary>
                  <div class="step-content">
                    <div class="step-actions"><a-button v-if="teacherAudit?.status === 'failed'" size="small" @click="openTeacherReview">重新启动</a-button><a-button v-else-if="!teacherAudit || teacherAudit.status === 'unavailable'" type="primary" size="small" @click="openTeacherReview">启动审计</a-button></div>
                  <a-spin :spinning="auditLoading">
                    <template v-if="teacherAudit?.status === 'completed'">
                      <section v-if="teacherAudit.selection.items.length" class="selection-record"><div class="section-heading"><span class="eyebrow">本次实际审阅材料</span><span>{{ selectionSourceLabel(teacherAudit.selection.source) }}</span></div><div class="selection-grid"><article v-for="item in teacherAudit.selection.items" :key="item.post_id" class="selection-item"><div><strong>{{ item.platform || '未知平台' }}</strong><span>{{ item.author_name || item.post_id }}</span></div><p>{{ item.excerpt || '原帖未保留可展示的文本摘要。' }}</p><dl><div><dt>转发</dt><dd>{{ item.reposts.toLocaleString() }}</dd></div><div><dt>点赞</dt><dd>{{ item.likes.toLocaleString() }}</dd></div><div><dt>评论</dt><dd>{{ item.comments.toLocaleString() }}</dd></div></dl></article></div></section>
                      <ol class="audit-trace"><li v-for="stage in visibleAuditStages" :key="`${stage.name}-${stage.role}`"><span class="trace-marker" :class="`state-${stage.status}`"></span><div><strong>{{ auditStageLabel(stage.name) }}</strong><p>{{ stage.summary || '已完成有界分析。' }}</p></div></li></ol>
                      <section v-if="teacherAudit.rationale.available" class="rationale-capsule"><span class="eyebrow">审计理由摘要</span><p>{{ teacherAudit.rationale.text }}</p><div v-if="teacherAudit.rationale.input_spans.length" class="reference-row"><span v-for="item in teacherAudit.rationale.input_spans" :key="item" class="reference-chip">{{ item }}</span></div></section>
                      <section v-if="teacherAudit.sources.length" class="audit-sources"><span class="eyebrow">审计证据引用</span><article v-for="source in teacherAudit.sources.slice(0, 5)" :key="source.source_id"><a :href="source.url || undefined" target="_blank" rel="noopener noreferrer">{{ source.title || source.source_id }}</a><p>{{ source.excerpt }}</p></article></section>
                    </template>
                    <a-alert v-else-if="teacherAudit?.status === 'queued'" type="info" show-icon message="智能审计正在进行" description="完成后将展示专家分析、定向反思与综合建议；不会展示完整推理过程。" />
                    <a-alert v-else-if="teacherAudit?.status === 'failed'" type="error" show-icon message="智能审计未完成" description="本次提供方或审计链路失败，未生成替代结论。确认配置后可重新启动。" />
                    <a-alert v-else type="info" show-icon message="尚未启动智能审计" description="由分析员启动后，系统会选择代表性高互动帖子并展示真实审计记录。" />
                  </a-spin>
                  </div>
                </details>
              </li>
              <li class="review-step" :class="{ 'is-blocked': teacherAudit?.status !== 'completed' }">
                <div class="step-rail"><span class="step-number">3</span></div>
                <details class="step-body">
                  <summary class="step-heading" aria-label="展开或收起本次审计使用的治理参考"><div><span class="eyebrow">审计引用</span><h4>本次审计使用的治理参考</h4></div><a-tag :color="governanceStateColor">{{ governanceStateLabel }}</a-tag></summary>
                  <div class="step-content">
                  <template v-if="teacherAudit?.status === 'completed' && teacherAudit.governance.available"><div class="governance-summary"><strong>{{ teacherAudit.governance.category || '治理参考' }}</strong><p v-if="teacherAudit.governance.recommended_actions.length">{{ teacherAudit.governance.recommended_actions.join('；') }}</p></div><a-list size="small" class="governance-list" :data-source="teacherAudit.governance.references"><template #renderItem="{ item }"><a-list-item><a :href="item.url || undefined" target="_blank" rel="noopener noreferrer">{{ item.title || item.reference_id }}</a><span class="reference-use">{{ item.governance_use }}</span></a-list-item></template></a-list></template>
                  <a-alert v-else-if="teacherAudit?.status === 'completed'" type="info" show-icon message="本次审计未使用治理参考" description="不会以当前静态治理库回填或补造引用。" />
                  <a-alert v-else type="info" show-icon message="等待审计完成" description="只有审计实际引用并持久化的治理参考会在此展示。" />
                  </div>
                </details>
              </li>
              <li class="review-step" :class="{ 'is-blocked': countermeasure?.status !== 'available' }">
                <div class="step-rail"><span class="step-number">4</span></div>
                <details class="step-body">
                  <summary class="step-heading" aria-label="展开或收起反制建议"><div><span class="eyebrow">审计后置草案</span><h4>反制建议</h4></div><a-tag :color="countermeasureStateColor">{{ countermeasureStateLabel }}</a-tag></summary>
                  <div class="step-content">
                  <a-spin :spinning="countermeasureLoading"><template v-if="countermeasure?.status === 'available'"><div class="countermeasure-actions"><span class="eyebrow">仅供人工确认</span><a-button size="small" @click="downloadCountermeasure">下载 Markdown</a-button></div><p class="report-summary">{{ countermeasure.risk_summary }}</p><div class="report-columns"><section><h5>建议人工处置</h5><ul><li v-for="item in countermeasure.recommended_actions" :key="item">{{ item }}</li></ul></section><section><h5>建议回应草案</h5><p>{{ countermeasure.response_draft }}</p></section></div><a-alert type="info" show-icon message="该草案不会自动发布或执行内容、账号处置。" /></template><a-alert v-else-if="countermeasure?.status === 'failed'" type="error" show-icon message="反制建议未生成" :description="countermeasure.reason || '反制报告生成失败，未提供替代草案。'" /><a-alert v-else type="info" show-icon message="尚未生成反制建议" :description="countermeasure?.reason || '审计完成、引用可追溯且质量门控通过后才会生成。'" /></a-spin>
                  </div>
                </details>
              </li>
            </ol>
          </section>
          <aside class="decision-column">
            <a-card size="small" title="人工决策草案" class="decision-card">
              <a-form v-if="!decisionLocked" layout="vertical" :disabled="savingDraft || confirming"><a-form-item label="确认结论" required><a-segmented v-model:value="draftForm.conclusion" :options="conclusionOptions" aria-label="确认结论" /></a-form-item><a-form-item label="紧急程度" required><a-segmented v-model:value="draftForm.urgency" :options="urgencyOptions" aria-label="紧急程度" /></a-form-item><a-form-item label="处置方式" required><a-select v-model:value="draftForm.disposition" :options="dispositionOptions" aria-label="处置方式" /></a-form-item><a-form-item label="结论依据" required><a-textarea v-model:value="draftForm.rationale" :rows="4" :maxlength="8000" name="decision-rationale" autocomplete="off" /></a-form-item><a-form-item label="关键引用"><a-textarea v-model:value="keyEvidenceInput" :rows="2" placeholder="每行一条引用" name="key-evidence" autocomplete="off" /></a-form-item><a-form-item label="待补事项"><a-textarea v-model:value="unresolvedInput" :rows="2" placeholder="每行一项" name="unresolved-items" autocomplete="off" /></a-form-item></a-form>
              <template v-if="!decisionLocked"><a-alert v-if="draftConflict" type="error" show-icon message="草稿已被其他分析员更新" description="请刷新案件后继续编辑。" /><div class="draft-status">{{ draftStatusText }}</div><a-space :size="8" wrap><a-button :disabled="!draftDirty || Boolean(draftConflict)" :loading="savingDraft" @click="saveDraftNow">保存草稿</a-button><a-button type="primary" danger :disabled="!canConfirmDecision" :loading="confirming" @click="openConfirmDecision">明确确认</a-button></a-space></template>
              <a-descriptions v-else :column="1" size="small" bordered><a-descriptions-item label="结论">{{ conclusionLabel(currentCase.confirmed_decision!.conclusion) }}</a-descriptions-item><a-descriptions-item label="紧迫度">{{ urgencyLabel(currentCase.confirmed_decision!.urgency) }}</a-descriptions-item><a-descriptions-item label="处置">{{ dispositionLabel(currentCase.confirmed_decision!.disposition) }}</a-descriptions-item><a-descriptions-item label="理由">{{ currentCase.confirmed_decision!.rationale }}</a-descriptions-item></a-descriptions>
            </a-card>
            <a-card size="small" title="业务活动" class="decision-card"><a-list size="small" :data-source="activities" :loading="activityLoading" class="activity-list"><template #renderItem="{ item }"><a-list-item><div><strong>{{ activityLabel(item.activity_type) }}</strong><p>{{ item.actor_name }} · {{ formatTime(item.occurred_at) }}</p></div></a-list-item></template></a-list><a-empty v-if="!activityLoading && !activities.length" description="暂无活动记录" :image-style="{ height: '38px' }" /></a-card>
          </aside>
        </section>
      </template>
    </a-spin>
    <a-modal v-model:open="reviewRequestOpen" title="启动智能审计" ok-text="启动审计" cancel-text="取消" :confirm-loading="reviewRequestSaving" @ok="submitReviewRequest"><a-form layout="vertical"><a-form-item label="审计范围"><a-tag color="blue">内容伤害</a-tag><p class="modal-help">将自动选择本案互动量较高的代表性帖子；不提交主张核验任务。</p></a-form-item><a-form-item label="审计原因" required><a-textarea v-model:value="reviewRequestReason" :rows="4" :maxlength="4000" show-count name="review-reason" autocomplete="off" /></a-form-item></a-form></a-modal>
  </div>
</template>

<script setup lang="ts">
import { computed, onActivated, onBeforeUnmount, onDeactivated, onMounted, reactive, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { Modal, message } from 'ant-design-vue'
import PageHeader from '@/components/PageHeader.vue'
import RiskSectionTabs from './RiskSectionTabs.vue'
import { confirmDecision, downloadCountermeasureMarkdown, getCountermeasureReport, getLatestReviewCase, getReviewAudit, getReviewCase, getStudentAssessment, isUnauthorizedCaseEventStreamError, listCaseActivities, readCaseEventStream, reassessStudent, requestReviewAdvisory, saveDecisionDraft, searchReviewCases } from '@/api/reviewCases'
import type { CaseActivity, CaseActivityType, CountermeasureReport, DecisionDraft, Disposition, EvidenceSufficiency, ReviewAudit, ReviewCaseDetail, ReviewCaseSummary, ReviewConclusion, ReviewUrgency, StudentAssessment } from '@/types/reviewCase'

type SelectOption = { label: string; value: string }
const route = useRoute(); const router = useRouter()
const currentCase = ref<ReviewCaseDetail | null>(null); const caseItems = ref<ReviewCaseSummary[]>([]); const selectedCaseId = ref<string>(); const loading = ref(false); const searching = ref(false); const activityLoading = ref(false); const activities = ref<CaseActivity[]>([]); const activityCursor = ref(0); const studentAssessment = ref<StudentAssessment | null>(null); const teacherAudit = ref<ReviewAudit | null>(null); const countermeasure = ref<CountermeasureReport | null>(null); const studentLoading = ref(false); const auditLoading = ref(false); const countermeasureLoading = ref(false); const studentRefreshing = ref(false); const reviewRequestOpen = ref(false); const reviewRequestSaving = ref(false); const reviewRequestReason = ref(''); const pageActive = ref(false); const savingDraft = ref(false); const confirming = ref(false); const draftVersion = ref(0); const draftDirty = ref(false); const draftConflict = ref(''); const keyEvidenceInput = ref(''); const unresolvedInput = ref('')
const draftForm = reactive<{ conclusion: ReviewConclusion; urgency: ReviewUrgency; disposition: Disposition; rationale: string }>({ conclusion: 'insufficient_evidence', urgency: 'watch', disposition: 'gather_evidence', rationale: '' })
let caseSearchTimer: number | undefined; let activityRecoveryTimer: number | undefined; let activityRecoveryController: AbortController | null = null; let draftSavePromise: Promise<DecisionDraft | null> | null = null; let caseLoadSequence = 0
const conclusionLabels: Record<ReviewConclusion, string> = { harmful: '存在风险', non_harmful: '风险不成立', insufficient_evidence: '暂不能确认' }; const sufficiencyLabels: Record<EvidenceSufficiency, string> = { sufficient: '充分', limited: '有限', insufficient: '不足' }; const urgencyLabels: Record<ReviewUrgency, string> = { routine: '常规关注', watch: '持续观察', urgent: '需尽快处理', critical: '需立即处理' }; const dispositionLabels: Record<Disposition, string> = { monitor: '继续监测', gather_evidence: '补充证据', escalate: '升级处置', respond: '对外回应', archive: '归档' }
const activityLabels: Record<CaseActivityType, string> = { case_created: '建立复核条目', snapshot_added: '更新事件材料', evidence_annotated: '证据标注', evidence_requested: '请求补充证据', review_requested: '启动智能审计', review_advisory_available: '智能审计完成', decision_draft_saved: '保存草稿', decision_confirmed: '确认结论', correction_recorded: '记录修正', reconfirmation_required: '需要重新确认', student_assessed: '刷新快速研判', teacher_review_failed: '智能审计失败', countermeasure_report_available: '生成反制建议草案' }
const conclusionOptions = typedOptions(conclusionLabels); const urgencyOptions = typedOptions(urgencyLabels); const dispositionOptions = typedOptions(dispositionLabels)
const riskScopeEventId = computed(() => currentCase.value?.event_id || queryText(route.query.event_id)); const riskScopeCaseId = computed(() => currentCase.value?.case_id || queryText(route.query.case_id)); const caseOptions = computed<SelectOption[]>(() => caseItems.value.map((item) => ({ label: item.title, value: item.case_id }))); const preliminaryNarrative = computed(() => conclusionNarrative(currentCase.value?.preliminary_finding.conclusion)); const visibleAuditStages = computed(() => (teacherAudit.value?.stages || []).filter((stage) => stage.name !== 'CountermeasureAgent')); const studentStateKey = computed(() => studentAssessment.value?.status || 'unavailable'); const studentStateLabel = computed(() => studentAssessment.value?.status === 'completed' ? '已完成' : studentAssessment.value?.status === 'unconfigured' ? '尚未部署' : studentAssessment.value?.status === 'failed' ? '运行失败' : '待读取'); const studentStateColor = computed(() => studentAssessment.value?.status === 'completed' ? 'blue' : studentAssessment.value?.status === 'failed' ? 'red' : 'default'); const auditStateKey = computed(() => teacherAudit.value?.status || 'unavailable'); const auditStateLabel = computed(() => teacherAudit.value?.status === 'completed' ? '已完成' : teacherAudit.value?.status === 'queued' ? '进行中' : teacherAudit.value?.status === 'failed' ? '未完成' : '待启动'); const auditStateColor = computed(() => teacherAudit.value?.status === 'completed' ? 'cyan' : teacherAudit.value?.status === 'queued' ? 'blue' : teacherAudit.value?.status === 'failed' ? 'red' : 'default'); const governanceStateLabel = computed(() => teacherAudit.value?.governance.available ? '已引用' : teacherAudit.value?.status === 'completed' ? '未使用' : '等待审计'); const governanceStateColor = computed(() => teacherAudit.value?.governance.available ? 'cyan' : 'default'); const countermeasureStateLabel = computed(() => countermeasure.value?.status === 'available' ? '草案已生成' : countermeasure.value?.status === 'failed' ? '生成失败' : '未生成'); const countermeasureStateColor = computed(() => countermeasure.value?.status === 'available' ? 'green' : countermeasure.value?.status === 'failed' ? 'red' : 'default'); const decisionLocked = computed(() => Boolean(currentCase.value?.confirmed_decision) && currentCase.value?.action_required !== 'reconfirm_decision'); const canConfirmDecision = computed(() => !decisionLocked.value && !draftConflict.value && Boolean(draftForm.rationale.trim())); const draftStatusText = computed(() => draftDirty.value ? '草稿有待保存的修改' : draftVersion.value > 0 ? '草稿已保存' : '请填写人工结论')
function typedOptions<T extends string>(labels: Record<T, string>) { return Object.entries(labels).map(([value, label]) => ({ value, label })) }; function queryText(value: unknown) { return Array.isArray(value) ? String(value[0] || '') : String(value || '') }; function taskLabel(task: string) { return task === 'interpersonal_harm' ? '内容伤害' : '主张核验' }; function axisStatusLabel(status: string) { return status === 'completed' ? '已完成' : status === 'unconfigured' ? '尚未部署' : status === 'failed' ? '运行失败' : '不可用' }; function axisStatusColor(status: string) { return status === 'completed' ? 'blue' : status === 'unconfigured' ? 'default' : 'red' }; function auditStageLabel(name: string) { return name === 'PostHarmAgent' ? '专家分析' : name === 'ClaimEvidenceAgent' ? '主张核验' : name === 'QuestionReflectionAgent' ? '定向反思' : '综合建议' }; function selectionSourceLabel(source: string) { return source === 'analyst_selected' ? '分析员指定' : '按互动量选取' }; function conclusionLabel(value: ReviewConclusion) { return conclusionLabels[value] }; function conclusionNarrative(value?: ReviewConclusion) { return value === 'harmful' ? '当前材料显示存在需要人工确认的风险线索。' : value === 'non_harmful' ? '当前材料未显示需要立即处置的明确风险。' : '当前材料尚不足以形成确定结论。' }; function sufficiencyLabel(value: EvidenceSufficiency) { return sufficiencyLabels[value] }; function urgencyLabel(value: ReviewUrgency) { return urgencyLabels[value] }; function dispositionLabel(value: Disposition) { return dispositionLabels[value] }; function activityLabel(value: CaseActivityType) { return activityLabels[value] || '事件更新' }; function percent(value: number | null) { return value === null ? '暂无' : `${(value * 100).toFixed(1)}%` }; function formatTime(value?: string | null) { if (!value) return '暂无'; const date = new Date(value); return Number.isNaN(date.getTime()) ? value : date.toLocaleString('zh-CN', { hour12: false }) }
async function loadInitialCase() { const linkedCaseId = queryText(route.query.case_id); const linkedEventId = queryText(route.query.event_id); if (linkedCaseId) return loadCase(linkedCaseId); if (linkedEventId) { const items = await loadCaseOptions(linkedEventId); const matched = items.find((item) => item.event_id === linkedEventId); if (matched) return loadCase(matched.case_id) }; loading.value = true; try { const response = await getLatestReviewCase(); await applyCase(response.data); void loadCaseOptions('') } catch { currentCase.value = null } finally { loading.value = false } }
async function loadCaseOptions(query: string) { const response = await searchReviewCases({ query, limit: 20 }); caseItems.value = response.data.items; return response.data.items }; function handleCaseSearch(query: string) { if (caseSearchTimer) window.clearTimeout(caseSearchTimer); caseSearchTimer = window.setTimeout(() => { void loadCaseOptions(query) }, 250) }; function handleCaseChange(value: string | undefined) { if (value) void loadCase(value) }; async function refreshCurrentCase() { if (currentCase.value) await loadCase(currentCase.value.case_id); else await loadInitialCase() }
async function loadCase(caseId: string) { const sequence = ++caseLoadSequence; loading.value = true; stopActivityRecovery(); studentAssessment.value = null; teacherAudit.value = null; countermeasure.value = null; try { const [detail, activity] = await Promise.all([getReviewCase(caseId), listCaseActivities(caseId, { limit: 100 })]); if (sequence !== caseLoadSequence) return; await applyCase(detail.data, activity.data) } finally { if (sequence === caseLoadSequence) loading.value = false } }
async function applyCase(detail: ReviewCaseDetail, activityData?: { items: CaseActivity[]; next_cursor: number | null }) { currentCase.value = detail; selectedCaseId.value = detail.case_id; hydrateDraft(detail); await router.replace({ query: { ...route.query, case_id: detail.case_id, event_id: detail.event_id } }); if (activityData) { activities.value = activityData.items; activityCursor.value = activityData.next_cursor || 0 } else await loadActivities(detail.case_id); void loadStudent(detail.case_id); void loadAudit(detail.case_id); startActivityRecovery(detail.case_id) }
async function loadStudent(caseId: string) { if (studentLoading.value) return; studentLoading.value = true; try { const response = await getStudentAssessment(caseId); if (currentCase.value?.case_id === caseId) studentAssessment.value = response.data } finally { studentLoading.value = false } }; async function loadAudit(caseId: string) { if (auditLoading.value) return; auditLoading.value = true; try { const response = await getReviewAudit(caseId); if (currentCase.value?.case_id === caseId) { teacherAudit.value = response.data; if (response.data.status === 'completed') void loadCountermeasure(caseId) } } finally { auditLoading.value = false } }; async function loadCountermeasure(caseId: string) { if (countermeasureLoading.value) return; countermeasureLoading.value = true; try { const response = await getCountermeasureReport(caseId); if (currentCase.value?.case_id === caseId) countermeasure.value = response.data } finally { countermeasureLoading.value = false } }
async function refreshStudent() { if (!currentCase.value) return; studentRefreshing.value = true; try { await reassessStudent(currentCase.value.case_id); await loadStudent(currentCase.value.case_id); message.success('已更新当前快照的初步研判') } catch { message.error('重新研判未完成，请查看状态后重试') } finally { studentRefreshing.value = false } }; function openTeacherReview() { reviewRequestReason.value = '复核本案代表性高互动帖子中的内容伤害风险。'; reviewRequestOpen.value = true }; async function submitReviewRequest() { if (!currentCase.value || !reviewRequestReason.value.trim()) { message.warning('请填写审计原因'); return }; reviewRequestSaving.value = true; try { await requestReviewAdvisory(currentCase.value.case_id, { reason: reviewRequestReason.value.trim(), evidence_refs: [], review_tasks: ['interpersonal_harm'] }); reviewRequestOpen.value = false; message.success('智能审计已启动'); await loadAudit(currentCase.value.case_id) } finally { reviewRequestSaving.value = false } }; async function downloadCountermeasure() { if (!currentCase.value) return; const response = await downloadCountermeasureMarkdown(currentCase.value.case_id); const url = URL.createObjectURL(response.data as Blob); const anchor = document.createElement('a'); anchor.href = url; anchor.download = `${currentCase.value.case_id}-countermeasure.md`; anchor.click(); URL.revokeObjectURL(url) }
function hydrateDraft(detail: ReviewCaseDetail) { const draft = detail.decision_draft; if (draft) { draftForm.conclusion = draft.conclusion; draftForm.urgency = draft.urgency; draftForm.disposition = draft.disposition; draftForm.rationale = draft.rationale; keyEvidenceInput.value = draft.key_evidence_refs.join('\n'); unresolvedInput.value = draft.unresolved_items.join('\n') } else if (detail.confirmed_decision) { const decision = detail.confirmed_decision; draftForm.conclusion = decision.conclusion; draftForm.urgency = decision.urgency; draftForm.disposition = decision.disposition; draftForm.rationale = decision.rationale; keyEvidenceInput.value = decision.key_evidence_refs.join('\n'); unresolvedInput.value = decision.unresolved_items.join('\n') } else if (detail.review_advisory) { const advisory = detail.review_advisory; draftForm.conclusion = advisory.conclusion; draftForm.urgency = advisory.urgency; draftForm.disposition = advisory.disposition; draftForm.rationale = advisory.rationale; keyEvidenceInput.value = advisory.key_evidence_refs.join('\n'); unresolvedInput.value = detail.missing_evidence.join('\n') } else { const preliminary = detail.preliminary_finding; draftForm.conclusion = preliminary.conclusion; draftForm.urgency = detail.urgency; draftForm.disposition = detail.disposition; draftForm.rationale = preliminary.rationale || conclusionNarrative(preliminary.conclusion); keyEvidenceInput.value = preliminary.key_evidence_refs.join('\n'); unresolvedInput.value = detail.missing_evidence.join('\n') }; draftVersion.value = draft?.draft_version || 0; draftDirty.value = !decisionLocked.value && !draft; draftConflict.value = '' }
watch([() => draftForm.conclusion, () => draftForm.urgency, () => draftForm.disposition, () => draftForm.rationale, keyEvidenceInput, unresolvedInput], () => { if (!decisionLocked.value) draftDirty.value = true })
async function saveDraftNow(): Promise<DecisionDraft | null> { if (!currentCase.value || decisionLocked.value || !draftForm.rationale.trim()) return null; if (draftSavePromise) return draftSavePromise; savingDraft.value = true; draftSavePromise = saveDecisionDraft(currentCase.value.case_id, { conclusion: draftForm.conclusion, urgency: draftForm.urgency, disposition: draftForm.disposition, rationale: draftForm.rationale.trim(), key_evidence_refs: splitLines(keyEvidenceInput.value), unresolved_items: splitLines(unresolvedInput.value), expected_version: draftVersion.value }).then((response) => { draftVersion.value = response.data.draft_version; draftDirty.value = false; if (currentCase.value) currentCase.value.decision_draft = response.data; message.success('草稿已保存'); return response.data }).catch((error: { response?: { status?: number } }) => { if (error?.response?.status === 409) { draftConflict.value = 'version_conflict'; message.warning('草稿已被其他分析员更新，请刷新后继续') }; return null }).finally(() => { savingDraft.value = false; draftSavePromise = null }); return draftSavePromise }
function openConfirmDecision() { Modal.confirm({ title: '确认提交当前结论？', content: '提交后将形成不可变更的确认结论。', okText: '明确确认', cancelText: '再检查', okButtonProps: { danger: true }, onOk: submitDecisionConfirmation }) }; async function submitDecisionConfirmation() { if (!currentCase.value || !canConfirmDecision.value) return; confirming.value = true; try { if (draftDirty.value || draftVersion.value === 0) { const saved = await saveDraftNow(); if (!saved) return }; await confirmDecision(currentCase.value.case_id, { expected_draft_version: draftVersion.value, confirmation_note: '已完成业务复核并确认结论。' }); message.success('确认结论已提交'); await loadCase(currentCase.value.case_id) } finally { confirming.value = false } }; function splitLines(value: string) { return value.split(/\r?\n/).map((item) => item.trim()).filter(Boolean) }
async function loadActivities(caseId: string) { activityLoading.value = true; try { const response = await listCaseActivities(caseId, { limit: 100 }); if (currentCase.value?.case_id === caseId) { activities.value = response.data.items; activityCursor.value = response.data.next_cursor || 0 } } finally { activityLoading.value = false } }; function startActivityRecovery(caseId: string) { stopActivityRecovery(); activityRecoveryTimer = window.setInterval(() => { void recoverCaseActivities(caseId) }, 10000) }; function stopActivityRecovery() { if (activityRecoveryTimer) window.clearInterval(activityRecoveryTimer); activityRecoveryTimer = undefined; activityRecoveryController?.abort(); activityRecoveryController = null }; async function recoverCaseActivities(caseId: string) { if (!pageActive.value || currentCase.value?.case_id !== caseId || activityRecoveryController) return; const controller = new AbortController(); activityRecoveryController = controller; try { const events = await readCaseEventStream(caseId, activityCursor.value, controller.signal); if (!events.length || currentCase.value?.case_id !== caseId) return; await loadActivities(caseId); if (events.some((event) => ['review_advisory_available', 'teacher_review_failed', 'countermeasure_report_available'].includes(event.activity_type))) { void loadAudit(caseId); void loadCountermeasure(caseId) }; if (events.some((event) => event.activity_type === 'student_assessed')) void loadStudent(caseId) } catch (error) { if (isUnauthorizedCaseEventStreamError(error)) stopActivityRecovery() } finally { if (activityRecoveryController === controller) activityRecoveryController = null } }
onMounted(() => { pageActive.value = true; void loadInitialCase() }); onActivated(() => { pageActive.value = true; if (currentCase.value) startActivityRecovery(currentCase.value.case_id) }); onDeactivated(() => { pageActive.value = false; stopActivityRecovery() }); onBeforeUnmount(() => { if (caseSearchTimer) window.clearTimeout(caseSearchTimer); stopActivityRecovery() })
</script>

