nt:vertical; -webkit-line-clamp:3; }.selection-item dl { gap:14px; margin-bottom:0; }.audit-trace { margin:14px 0 0; padding:4px 0 4px 20px; list-style:none; }.audit-trace li { position:relative; display:grid; grid-template-columns:22px minmax(0,1fr); padding:0 0 15px; }.audit-trace li:not(:last-child)::before { position:absolute; top:17px; left:5px; width:1px; height:calc(100% - 2px); background:#c7d9dd; content:''; }.trace-marker { width:11px; height:11px; margin-top:5px; border-radius:50%; background:#7e9ea5; }.trace-marker.state-completed { background:#1f7e74; }.trace-marker.state-failed { background:#bd4c43; }.rationale-capsule p,.report-summary { margin:6px 0 0; line-height:1.7; }.reference-row { display:flex; gap:6px; flex-wrap:wrap; margin-top:8px; }.reference-chip { padding:3px 7px; color:#45626c; background:#e7f0f1; font-size:12px; }.audit-sources article { padding:9px 0; border-bottom:1px solid #e1e8e9; }.audit-sources a { color:#176c79; }.governance-list { margin-top:10px; }.reference-use { margin-left:8px; color:#71808a; font-size:12px; }.countermeasure-actions { margin-bottom:8px; }.report-columns { margin:14px 0; }.report-columns section { min-width:0; padding:12px; background:#f7faf9; }.report-columns h5 { margin:0 0 8px; font-size:13px; }.report-columns p,.report-columns ul { margin:0; padding-left:18px; line-height:1.7; }.axis-panel p,.audit-trace p,.audit-sources p,.audit-sources a,.rationale-capsule p,.governance-summary p,.reference-use,.reference-chip,.report-summary,.report-columns p,.report-columns li,.selection-item p { overflow-wrap:anywhere; word-break:break-word; }.decision-column { display:grid; gap:14px; min-width:0; }.decision-card { border-radius:6px; }.draft-status { margin:10px 0; color:#71808a; font-size:12px; }.activity-list strong { font-size:13px; }.activity-list p { margin-top:2px; font-size:12px; }.modal-help { margin:8px 0 0; color:#687680; font-size:13px; line-height:1.6; }@media (max-width:900px) { .case-toolbar,.workbench-